const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const pascal = (s) => s.replace(/(^|[^A-Za-z0-9])([a-z])/g, (_, __, c) => c.toUpperCase());

const parts = (raw) => raw.split(/\{\{([\s\S]+?)\}\}/g);
const isDyn = (raw) => raw.includes('{{');

function expr(path, scope) {
  const p = path.trim();
  if (/^-?\d+(\.\d+)?$/.test(p) || p === 'true' || p === 'false' || p === 'null') return p;
  const seg = p.split('.');
  if (seg[0] === '$index') return scope.index || 'undefined';
  const head = scope.vars.includes(seg[0]) ? seg[0] : '$.' + seg[0];
  return [head, ...seg.slice(1)].join('?.');
}
function value(raw, scope) {
  const whole = raw.match(/^\s*\{\{([\s\S]+?)\}\}\s*$/);
  if (whole) return expr(whole[1], scope);
  if (!isDyn(raw)) return JSON.stringify(raw);
  const body = parts(raw).map((s, i) => (i & 1 ? '${' + expr(s, scope) + ' ?? ""}' : s.replace(/[`\\$]/g, '\\$&'))).join('');
  return '`' + body + '`';
}
function splitDecls(css) {
  const out = []; let cur = '', depth = 0, q = null, tpl = 0;
  for (let i = 0; i < css.length; i++) {
    const c = css[i];
    if (css.startsWith('{{', i)) tpl++; else if (css.startsWith('}}', i)) tpl = Math.max(0, tpl - 1);
    if (q) { if (c === q) q = null; } else if (c === '"' || c === "'") q = c;
    else if (c === '(') depth++; else if (c === ')') depth--;
    if (c === ';' && !q && !depth && !tpl) { out.push(cur); cur = ''; } else cur += c;
  }
  if (cur.trim()) out.push(cur);
  return out;
}
function styleObj(raw, scope) {
  const items = [];
  for (const decl of splitDecls(raw)) {
    if (!decl.trim()) continue;
    const i = decl.indexOf(':');
    if (i < 0) { if (isDyn(decl)) items.push('...css(' + value(decl, scope) + ')'); continue; }
    const prop = decl.slice(0, i).trim();
    if (isDyn(prop)) { items.push('...css(' + value(decl, scope) + ')'); continue; }
    const k = prop.startsWith('--') ? JSON.stringify(prop) : camel(prop);
    items.push(k + ': ' + value(decl.slice(i + 1).trim(), scope));
  }
  return '{ ' + items.join(', ') + ' }';
}
const childrenOf = (n) => (n.children || []).filter((c) => c.type === 'tag' || c.type === 'text' || c.type === 'style');

function text(n, parent, idx, sibs, scope) {
  const raw = n.data;
  if (!raw.trim()) {
    if (idx === 0 || idx === sibs.length - 1 || NO_WS.has(parent)) return '';
    const inl = (m) => m && m.type === 'tag' && INLINE.has(m.name);
    return inl(sibs[idx - 1]) || inl(sibs[idx + 1]) ? '{" "}' : '';
  }
  const collapsed = raw.replace(/\s+/g, ' ');
  return parts(collapsed).map((s, i) => {
    if (i & 1) return '{' + expr(s, scope) + '}';
    if (!s) return '';
    return '{' + JSON.stringify(s) + '}';
  }).join('');
}
function kids(n, scope) {
  const sibs = childrenOf(n);
  return sibs.map((c, i) => (c.type === 'text' ? text(c, n.name, i, sibs, scope) : node(c, scope))).join('');
}
function importProps(n, scope, skip) {
  const out = [];
  for (const [k, v] of Object.entries(n.attribs)) {
    if (skip.includes(k) || k === 'hint-size' || k === 'style' || k.startsWith('hint-')) continue;
    const key = (k.startsWith('aria-') || k.startsWith('data-')) ? k : camel(k);
    out.push(key + '={' + value(v, scope) + '}');
  }
  return out.join(' ');
}
function node(n, scope) {
  if (n.type === 'style') return '<style dangerouslySetInnerHTML={{ __html: ' + JSON.stringify(DomUtils.textContent(n)) + ' }} />';
  const tag = n.name;
  if (tag === 'helmet' || tag === 'script') return '';
  if (tag === 'sc-if') return '{' + expr(n.attribs.value.replace(/[{}]/g, ''), scope) + ' ? <>' + kids(n, scope) + '</> : null}';
  if (tag === 'sc-for') {
    const as = n.attribs.as || 'item', idx = '__i' + scope.vars.length;
    const sub = { vars: [...scope.vars, as], index: idx };
    return '{arr(' + expr(n.attribs.list.replace(/[{}]/g, ''), scope) + ').map((' + as + ', ' + idx + ') => <React.Fragment key={' + idx + '}>' + kids(n, sub) + '</React.Fragment>)}';
  }
  if (tag === 'dc-import') {
    deps.add(n.attribs.name);
    const st = n.attribs.style ? ' style={hostStyle(' + styleObj(n.attribs.style, scope) + ')}' : '';
    const inner = '<DC_' + n.attribs.name + ' ' + importProps(n, scope, ['name']) + ' />';
    return '<div data-sc-name=' + JSON.stringify(n.attribs.name) + st + '>' + (OVERRIDE[n.attribs.name] || n.attribs.name === 'TradeHistory' || n.attribs.name === 'Portfolio' ? '<ScreenBoundary>' + inner + '</ScreenBoundary>' : inner) + '</div>';
  }
  if (tag === 'x-import') {
    const comp = n.attribs['component-from-global-scope'].replace(/^QL\./, 'QLG.');
    const el = '<' + comp + ' ' + importProps(n, scope, ['component-from-global-scope']) + ' />';
    return n.attribs.style ? '<div style={hostStyle(' + styleObj(n.attribs.style, scope) + ') || { display: "contents" }}>' + el + '</div>' : el;
  }
  const attrs = [], cls = [];
  for (const [k, v] of Object.entries(n.attribs)) {
    if (k.startsWith('hint-') || k === 'sc-name') continue;
    if (k === 'style') { attrs.push('style={' + styleObj(v, scope) + '}'); continue; }
    if (k.startsWith('style-')) { cls.push('ps(' + JSON.stringify(k.slice(6)) + ', ' + value(v, scope) + ')'); continue; }
    if (k === 'class') { cls.push(value(v, scope)); continue; }
    const key = ATTR[k] || k;
    if (BOOL.has(key) && !isDyn(v)) { attrs.push(key + '={true}'); continue; }
    attrs.push(key + '={' + value(v, scope) + '}');
  }
  if (cls.length) attrs.push('className={' + cls.join(' + " " + ') + '}');
  const open = '<' + tag + (attrs.length ? ' ' + attrs.join(' ') : '');
  if (VOID.has(tag)) return open + ' />';
  return open + '>' + kids(n, scope) + '</' + tag + '>';
}
let deps = new Set();
const names = [];
const REPLACED = new Set(['Auth', 'Integrations', 'Optimizer', 'Settings']);
for (const file of readdirSync(SRC).filter((f) => f.endsWith('.dc.html') && !REPLACED.has(f.replace('.dc.html', ''))).sort()) {
  const name = file.replace('.dc.html', ''); names.push(name); deps = new Set();
  let html = readFileSync(join(SRC, file), 'utf8');
  for (const [from, to] of PATCH[name] || []) {
    if (typeof from === 'string' ? !html.includes(from) : !from.test(html)) throw new Error(file + ': patch target missing: ' + from);
    html = html.replace(from, to);
  }
  const tplStart = html.indexOf('<x-dc>') + 6, tplEnd = html.lastIndexOf('</x-dc>');
  const m = html.slice(tplEnd).match(/<script type="text\/x-dc"[^>]*data-props="([^"]*)"[^>]*>([\s\S]*?)<\/script>/);
  if (!m) throw new Error(file + ': no logic script');
  const doc = parseDocument(html.slice(tplStart, tplEnd), { lowerCaseTags: false, lowerCaseAttributeNames: false, recognizeSelfClosing: true, decodeEntities: true });
  const jsx = kids({ name: 'root', children: doc.children }, { vars: [], index: null });
  const meta = JSON.parse(m[1].replace(/&quot;/g, '"').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&'));
  const defaults = Object.fromEntries(Object.entries(meta).filter(([, v]) => v && 'default' in v).map(([k, v]) => [k, v.default]));
  const imports = [...deps].sort().map((d) => `import DC_${d} from '${OVERRIDE[d] || './' + d}';`).join('\n');
  writeFileSync(join(OUT, name + '.tsx'), `// @ts-nocheck
// GENERATED by scripts/dc2tsx.mjs from design-source/${file}. Do not edit: regenerate.
'use client';
import React from 'react';
import QLG from '@/lib/ql';
import { DCLogic, ScreenBoundary, arr, css, hostStyle, ps } from '@/lib/dc';
${imports}

${m[2].trim()}

export default class ${name}Screen extends Component {
  static defaultProps = ${JSON.stringify(defaults)};
  render() {
    const $ = { ...this.props, ...(this.renderVals() || {}) };
    return (<>${jsx}</>);
  }
}
`);
}
console.log('generated', names.length, 'screens');
